-- CR-25 change 11: State and District master data, and the business address
-- split into fields. Existing data is kept: the old free-text address stays
-- in business_profiles.address and is also copied into address_line1 so the
-- owner only has to add the district and PIN code.
--
-- States and union territories come from the Local Government Directory
-- (https://lgdirectory.gov.in, state list read 25 Nov 2026), with their GST
-- state codes. Districts are loaded by 20261126000002_seed_states_districts
-- (generated by tool/import_lgd.dart from the LGD district download).
-- Both tables can be read by any signed-in user and written by nobody.
begin;

create table if not exists public.states (
  id bigint generated always as identity primary key,
  lgd_code integer not null unique,
  name text not null unique,
  gst_state_code text not null unique check (gst_state_code ~ '^[0-9]{2}$'),
  type text not null check (type in ('State', 'UT'))
);

create table if not exists public.districts (
  id bigint generated always as identity primary key,
  lgd_code integer not null unique,
  name text not null,
  state_id bigint not null references public.states (id),
  unique (state_id, name)
);
create index if not exists districts_state_id_idx on public.districts (state_id);

alter table public.states enable row level security;
alter table public.districts enable row level security;
revoke all on public.states, public.districts from anon, authenticated;
grant select on public.states, public.districts to authenticated;
drop policy if exists "Signed-in users read states" on public.states;
create policy "Signed-in users read states" on public.states
  for select to authenticated using (true);
drop policy if exists "Signed-in users read districts" on public.districts;
create policy "Signed-in users read districts" on public.districts
  for select to authenticated using (true);

insert into public.states (lgd_code, name, gst_state_code, type) values
  (35, 'Andaman and Nicobar Islands', '35', 'UT'),
  (28, 'Andhra Pradesh', '37', 'State'),
  (12, 'Arunachal Pradesh', '12', 'State'),
  (18, 'Assam', '18', 'State'),
  (10, 'Bihar', '10', 'State'),
  (4, 'Chandigarh', '04', 'UT'),
  (22, 'Chhattisgarh', '22', 'State'),
  (38, 'Dadra and Nagar Haveli and Daman and Diu', '26', 'UT'),
  (7, 'Delhi', '07', 'UT'),
  (30, 'Goa', '30', 'State'),
  (24, 'Gujarat', '24', 'State'),
  (6, 'Haryana', '06', 'State'),
  (2, 'Himachal Pradesh', '02', 'State'),
  (1, 'Jammu and Kashmir', '01', 'UT'),
  (20, 'Jharkhand', '20', 'State'),
  (29, 'Karnataka', '29', 'State'),
  (32, 'Kerala', '32', 'State'),
  (37, 'Ladakh', '38', 'UT'),
  (31, 'Lakshadweep', '31', 'UT'),
  (23, 'Madhya Pradesh', '23', 'State'),
  (27, 'Maharashtra', '27', 'State'),
  (14, 'Manipur', '14', 'State'),
  (17, 'Meghalaya', '17', 'State'),
  (15, 'Mizoram', '15', 'State'),
  (13, 'Nagaland', '13', 'State'),
  (21, 'Odisha', '21', 'State'),
  (34, 'Puducherry', '34', 'UT'),
  (3, 'Punjab', '03', 'State'),
  (8, 'Rajasthan', '08', 'State'),
  (11, 'Sikkim', '11', 'State'),
  (33, 'Tamil Nadu', '33', 'State'),
  (36, 'Telangana', '36', 'State'),
  (16, 'Tripura', '16', 'State'),
  (9, 'Uttar Pradesh', '09', 'State'),
  (5, 'Uttarakhand', '05', 'State'),
  (19, 'West Bengal', '19', 'State')
on conflict (lgd_code) do update set
  name = excluded.name,
  gst_state_code = excluded.gst_state_code,
  type = excluded.type;

-- Business address in fields (BUILD-STANDARDS section 2). Lengths match the
-- app; NOT VALID so existing rows are never rejected, only new writes.
alter table public.business_profiles
  add column if not exists address_line1 text,
  add column if not exists address_line2 text,
  add column if not exists landmark text,
  add column if not exists city text,
  add column if not exists district text,
  add column if not exists pincode text;

alter table public.business_profiles drop constraint if exists business_profiles_address_lengths;
alter table public.business_profiles add constraint business_profiles_address_lengths check (
  coalesce(char_length(address_line2), 0) <= 150
  and coalesce(char_length(landmark), 0) <= 150
  and coalesce(char_length(city), 0) <= 100
  and coalesce(char_length(district), 0) <= 100
) not valid;
alter table public.business_profiles drop constraint if exists business_profiles_pincode_format;
alter table public.business_profiles add constraint business_profiles_pincode_format
  check (pincode is null or pincode = '' or pincode ~ '^[1-9][0-9]{5}$') not valid;

-- Existing businesses: the old one-box address becomes line 1.
update public.business_profiles
set address_line1 = address
where coalesce(btrim(address_line1), '') = ''
  and coalesce(btrim(address), '') <> '';

notify pgrst, 'reload schema';
commit;
